import React from "react";
import styled from "styled-components"; // Import styled-components
import { AppProvider } from "./context/AppContext";
import EarthViewer from "./components/EarthViewer";
import ControlPanel from "./components/ControlPanel";
import CountryInfo from "./components/CountryInfo";
import SettingsPanel from "./components/SettingsPanel";
import KeyboardShortcuts from "./components/KeyboardShortcuts";
import "./App.css";

// Styled Components
const AppWrapper = styled.div`
  position: relative;
  width: 100%;
  height: 100vh;
  overflow: hidden;
  background-color: #1a202c; /* bg-space-dark - Assuming a dark slate color */
  /* className="App" is kept for potential global styles in App.css */
`;

const HelpBadgeStyled = styled.div`
  // Renamed to avoid conflict if HelpBadge becomes a component
  position: absolute;
  bottom: 1rem; /* bottom-4 */
  left: 1rem; /* left-4 */
  font-size: 0.75rem; /* text-xs */
  color: #9ca3af; /* text-gray-400 */
  background-color: rgba(0, 0, 0, 0.5); /* bg-black bg-opacity-50 */
  padding: 0.5rem 0.75rem; /* px-3 py-2 */
  border-radius: 0.5rem; /* rounded-lg */
`;

const HelpBadgeTitle = styled.div`
  font-weight: 500; /* font-medium */
`;

const HelpBadgeText = styled.div`
  color: #6b7280; /* text-gray-500 */
`;

const HelpBadgeTextWithMargin = styled(HelpBadgeText)`
  margin-top: 0.25rem; /* mt-1 */
`;

// Wrapper components with console logs
const EarthViewerWrapper = () => {
  console.log("EarthViewer rendering (via wrapper)");
  return <EarthViewer />;
};

const ControlPanelWrapper = () => {
  console.log("ControlPanel rendering (via wrapper)");
  return <ControlPanel />;
};

const CountryInfoWrapper = () => {
  console.log("CountryInfo rendering (via wrapper)");
  return <CountryInfo />;
};

const SettingsPanelWrapper = () => {
  console.log("SettingsPanel rendering (via wrapper)");
  return <SettingsPanel />;
};

const KeyboardShortcutsWrapper = () => {
  console.log("KeyboardShortcuts rendering (via wrapper)");
  return <KeyboardShortcuts />;
};

const HelpBadgeComponentWrapper = () => {
  console.log("HelpBadge rendering (via wrapper)");
  return (
    <HelpBadgeStyled>
      <HelpBadgeTitle>Interactive Earth Viewer</HelpBadgeTitle>
      <HelpBadgeText>
        Mouse: Rotate • Scroll: Zoom • Click: Select Country
      </HelpBadgeText>
      <HelpBadgeTextWithMargin>
        Shortcuts: C (Controls) • S (Settings) • R (Record) • F (Fullscreen) •
        Space (Pause)
      </HelpBadgeTextWithMargin>
    </HelpBadgeStyled>
  );
};

function App() {
  console.log("App component rendering");

  return (
    <AppProvider>
      <AppWrapper className="App">
        {/* Keyboard shortcuts handler */}
        <KeyboardShortcutsWrapper />

        {/* Main Earth Viewer */}
        <EarthViewerWrapper />

        {/* UI Overlays */}
        <ControlPanelWrapper />
        <CountryInfoWrapper />
        <SettingsPanelWrapper />

        {/* Help Badge */}
        <HelpBadgeComponentWrapper />
      </AppWrapper>
    </AppProvider>
  );
}

export default App;
